    # Check if the row is already 'abc'
    if cards[0] == 'a' and cards[1] == 'b' and cards[2] == 'c':
        return True

    # Check if the row can be made 'abc' with at most one operation
    for i in range(3):
        if cards[i] == 'a':
            if cards[i-1] == 'b' and cards[i+1] == 'c':
                return True

    return False

