    # Check if the string is a binary representation of a power of 5
    if not s[1] == '1':
        return -1

    # If both conditions are met, return the minimum number of substrings
    if s[0] == '1' and s[1] == '1':
        return len(s)

    # If the string is not a power of 5, return -1
    else:
        return -1

